function hydrateChangesList() {
  const list = document.getElementById('changes-list');
  if (!list || list.children.length) return;
  fetch('log.json')
    .then((r) => r.json())
    .then((rows) => {
      if (!Array.isArray(rows)) return;
      const landed = rows.filter((row) => row && row.state === 'landed');
      landed.forEach((row) => {
        const li = document.createElement('li');
        const when = row.run_at || row.tick_id || '';
        const what = row.changed_paths || '';
        li.textContent = when + ' — ' + what;
        list.appendChild(li);
      });
    })
    .catch(() => {
      // log.json unavailable; leave the list as-is
    });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', hydrateChangesList);
} else {
  hydrateChangesList();
}
```

