// Populate the changes page #changes-list from site/log.json (real landed
// ticks), so the list is truthful and never drifts stale. Only fills an empty
// list; if log.json is unavailable the static markup is left intact.
function hydrateChangesList() {
  const list = document.getElementById('changes-list');
  if (!list || list.children.length) return;
  fetch('log.json')
    .then((r) => r.json())
    .then((rows) => {
