// ==== Changes list hydration ====
// Populate #changes-list from site/log.json (landed ticks, newest first) so the
// Changes page is never empty and the export buttons have real rows to work
// with. Guarded: a failed fetch or an unexpected schema leaves the list as-is.
function hydrateChangesList() {
  const list = document.getElementById('changes-list');
  if (!list) return;
  fetch('log.json')
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error('log.json unavailable'))))
    .then((entries) => {
      if (!Array.isArray(entries)) return;
      list.textContent = '';
      entries.forEach((entry) => {
        if (!entry || entry.state !== 'landed' || !entry.changed_paths) return;
        const li = document.createElement('li');
        li.textContent = (entry.run_at || entry.tick_id || '') + ' — ' + entry.changed_paths;
        list.appendChild(li);
      });
    })
    .catch(() => {
      // log.json unavailable; leave the list as-is
    });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', hydrateChangesList);
} else {
  hydrateChangesList();
}
```

